<?php
/**
 * QPOS List Products synchronized scrollbar installer.
 * Upload beside public/index.php, run once with the required key, then delete it.
 */
header('Content-Type: text/html; charset=UTF-8');

$requiredKey = 'qposclear2026';
$providedKey = isset($_GET['key']) ? (string) $_GET['key'] : '';
$keyValid = function_exists('hash_equals')
    ? hash_equals($requiredKey, $providedKey)
    : $requiredKey === $providedKey;

if (!$keyValid) {
    http_response_code(403);
    echo '<!doctype html><html><head><meta charset="utf-8"><title>QPOS installer</title></head><body>';
    echo '<h1>Access denied</h1><p>The installer key is missing or invalid.</p></body></html>';
    exit;
}

$payloads = array(
    'resources/views/product/index.blade.php' => array('sha1' => '70114e93947f08a659c16a36088a4482e11d6cab', 'data' => ''),
    'resources/views/product/partials/product_list.blade.php' => array('sha1' => 'f2ab63ef0ab084c62321a87f82f31eebe67e52bf', 'data' => '')
);

$messages = array();
$errors = array();
$backups = array();
$writtenFiles = array();

function qpos_h($value)
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

function qpos_find_laravel_root($payloads)
{
    $candidates = array(__DIR__, dirname(__DIR__));
    foreach ($candidates as $candidate) {
        $candidate = realpath($candidate);
        if ($candidate === false) {
            continue;
        }
        $allParentsExist = true;
        foreach (array_keys($payloads) as $relativePath) {
            if (!is_dir($candidate . DIRECTORY_SEPARATOR . dirname($relativePath))) {
                $allParentsExist = false;
                break;
            }
        }
        if ($allParentsExist && (is_file($candidate . '/artisan') || is_file($candidate . '/bootstrap/app.php'))) {
            return $candidate;
        }
    }
    return false;
}

function qpos_backup_name($target, $stamp)
{
    $base = $target . '.qpos-scroll-backup-' . $stamp;
    $candidate = $base;
    $counter = 1;
    while (file_exists($candidate)) {
        $candidate = $base . '-' . $counter;
        $counter++;
    }
    return $candidate;
}

function qpos_atomic_write($target, $contents, &$error)
{
    $directory = dirname($target);
    $temporary = tempnam($directory, '.qpos-scroll-');
    if ($temporary === false) {
        $error = 'Could not create a temporary file in ' . $directory;
        return false;
    }

    $expectedLength = strlen($contents);
    $written = @file_put_contents($temporary, $contents, LOCK_EX);
    if ($written !== $expectedLength) {
        @unlink($temporary);
        $error = 'Could not write the complete temporary payload for ' . $target;
        return false;
    }
    if (sha1_file($temporary) !== sha1($contents)) {
        @unlink($temporary);
        $error = 'Temporary payload verification failed for ' . $target;
        return false;
    }

    if (file_exists($target)) {
        $permissions = @fileperms($target);
        if ($permissions !== false) {
            @chmod($temporary, $permissions & 0777);
        }
    } else {
        @chmod($temporary, 0644);
    }

    if (!@rename($temporary, $target)) {
        @unlink($temporary);
        $error = 'Atomic replacement failed for ' . $target;
        return false;
    }
    return true;
}

function qpos_clear_compiled_views($directory)
{
    $cleared = 0;
    if (!is_dir($directory)) {
        return $cleared;
    }
    try {
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::CHILD_FIRST
        );
        foreach ($iterator as $item) {
            if ($item->isFile() && strtolower($item->getExtension()) === 'php' && @unlink($item->getPathname())) {
                $cleared++;
            }
        }
    } catch (Exception $exception) {
        // Installation remains valid; the result page reports that no more files were cleared.
    }
    return $cleared;
}

$root = qpos_find_laravel_root($payloads);
if ($root === false) {
    $errors[] = 'Laravel root was not found at the installer directory or its parent.';
} else {
    $messages[] = 'Laravel root: ' . $root;
    $decodedPayloads = array();

    foreach ($payloads as $relativePath => $payload) {
        $decoded = base64_decode($payload['data'], true);
        if ($decoded === false) {
            $errors[] = 'Strict Base64 validation failed: ' . $relativePath;
            continue;
        }
        if (sha1($decoded) !== $payload['sha1']) {
            $errors[] = 'SHA1 validation failed: ' . $relativePath;
            continue;
        }
        $decodedPayloads[$relativePath] = $decoded;
        $messages[] = 'Payload validated: ' . $relativePath . ' (' . $payload['sha1'] . ')';
    }

    if (count($decodedPayloads) === count($payloads) && count($errors) === 0) {
        $stamp = gmdate('Ymd-His');
        foreach ($decodedPayloads as $relativePath => $decoded) {
            $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relativePath);
            if (file_exists($target)) {
                $backup = qpos_backup_name($target, $stamp);
                if (!@copy($target, $backup) || sha1_file($backup) !== sha1_file($target)) {
                    $errors[] = 'Verified backup failed: ' . $relativePath;
                    break;
                }
                $backups[] = $backup;
                $messages[] = 'Backup created: ' . $backup;
            }
        }

        if (count($errors) === 0) {
            foreach ($decodedPayloads as $relativePath => $decoded) {
                $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relativePath);
                $writeError = '';
                if (!qpos_atomic_write($target, $decoded, $writeError)) {
                    $errors[] = $writeError;
                    break;
                }
                if (sha1_file($target) !== $payloads[$relativePath]['sha1']) {
                    $errors[] = 'Post-write SHA1 verification failed: ' . $relativePath;
                    break;
                }
                $writtenFiles[] = $target;
                $messages[] = 'Installed and verified: ' . $relativePath;
            }
        }

        if (count($errors) === 0) {
            $compiledDirectory = $root . '/storage/framework/views';
            $cleared = qpos_clear_compiled_views($compiledDirectory);
            $messages[] = 'Cleared ' . $cleared . ' compiled Blade view file(s).';

            if (function_exists('opcache_invalidate')) {
                foreach ($writtenFiles as $writtenFile) {
                    @opcache_invalidate($writtenFile, true);
                }
                $messages[] = 'OPcache entries invalidated.';
            }
            if (function_exists('opcache_reset')) {
                @opcache_reset();
                $messages[] = 'OPcache reset requested.';
            }
        }
    }
}

$success = count($errors) === 0 && count($writtenFiles) === count($payloads);
http_response_code($success ? 200 : 500);
?>
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>QPOS Product Table Scroll Installer</title>
    <style>
        body { margin: 0; padding: 32px 18px; background: #f4f7fb; color: #172033; font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
        main { max-width: 900px; margin: auto; background: #fff; padding: 28px; border-radius: 12px; box-shadow: 0 8px 28px rgba(22, 34, 56, .12); }
        h1 { margin-top: 0; } .ok { color: #146c43; } .bad, .warning { color: #a32323; }
        li { margin: 8px 0; overflow-wrap: anywhere; } .warning { margin-top: 28px; padding: 16px; border: 2px solid #d33; background: #fff3f3; font-weight: 700; }
        code { background: #eef1f6; padding: 2px 5px; border-radius: 4px; }
    </style>
</head>
<body><main>
    <h1 class="<?php echo $success ? 'ok' : 'bad'; ?>"><?php echo $success ? 'Installation completed' : 'Installation failed'; ?></h1>
    <?php if (count($messages) > 0): ?><h2>Results</h2><ul><?php foreach ($messages as $message): ?><li><?php echo qpos_h($message); ?></li><?php endforeach; ?></ul><?php endif; ?>
    <?php if (count($errors) > 0): ?><h2 class="bad">Errors</h2><ul><?php foreach ($errors as $error): ?><li class="bad"><?php echo qpos_h($error); ?></li><?php endforeach; ?></ul><?php endif; ?>
    <?php if (count($backups) > 0): ?><h2>Backups</h2><ul><?php foreach ($backups as $backup): ?><li><code><?php echo qpos_h($backup); ?></code></li><?php endforeach; ?></ul><?php endif; ?>
    <p class="warning">Security warning: delete <code>qpos_install_product_table_scroll.php</code> from the server immediately after use, then hard-refresh the List Products page.</p>
</main></body></html>
